from qgis.PyQt.QtWidgets import QAction
from qgis.PyQt.QtCore import QEventLoop, QTimer

mw = iface.mainWindow()
out = {}
act = None
for a in mw.findChildren(QAction):
    if a.objectName() == 'mFloaterAction':
        act = a
        break

if act is None:
    result = {'error': 'not found'}
else:
    out['before'] = {'enabled': act.isEnabled(), 'checked': act.isChecked()}
    # シグナル発行を検知
    fired = {'n': 0}
    act.toggled.connect(lambda v: fired.__setitem__('n', fired['n'] + 1))
    act.trigger()
    out['after_trigger'] = {'checked': act.isChecked(), 'toggled_fired': fired['n']}
result = out
"}

